export const DEFAULT_STRUCTURES: Record<string, string> = {
  "1HSG": STRUCTURE_1HSG,
  "6LU7": STRUCTURE_6LU7,
};

export const DEFAULT_LIGANDS: Record<string, string> = {
  "1HSG": LIGAND_1HSG_MK1,
  "6LU7": LIGAND_6LU7_N3,
  "MK1": LIGAND_1HSG_MK1,
  "INDINAVIR": LIGAND_1HSG_MK1,
  "DRUG A": LIGAND_6LU7_N3,
  "DRUG B": LIGAND_1HSG_MK1,
  "DRUG C": LIGAND_1HSG_MK1,
};

export function getDefaultProteinStructure(key?: string): string | undefined {
  if (!key) return STRUCTURE_1HSG;
  const upper = key.toUpperCase();
  if (DEFAULT_STRUCTURES[upper]) return DEFAULT_STRUCTURES[upper];
  if (upper.includes("1HSG") || upper.includes("HIV") || upper.includes("RETROPEPSIN")) return STRUCTURE_1HSG;
  if (upper.includes("6LU7") || upper.includes("SARS") || upper.includes("MPRO") || upper.includes("COVID")) return STRUCTURE_6LU7;
  return STRUCTURE_1HSG;
}

export function getDefaultLigandCoordinates(key?: string): string {
  if (!key) return LIGAND_1HSG_MK1;
  const upper = key.toUpperCase();
  if (DEFAULT_LIGANDS[upper]) return DEFAULT_LIGANDS[upper];
  if (upper.includes("DRUG A") || upper.includes("NIRMATRELVIR") || upper.includes("N3")) return LIGAND_6LU7_N3;
  return LIGAND_1HSG_MK1;
}
